      <p
        class="render-sub"
      >Here’s a sneak peak of some delightful designs created on Neo, all within minutes!</p>
      <div class="render-slider">
        <div class="transition-group" ref="slider" @click="stopBgScroll">
          <div class="image-container" v-for="(render,index) in renderData">
            <img :src="render.image" />
            <div class="image-text">
              <p>{{render.title}}</p>
              <span>{{render.subtitle}}</span>
            </div>
            <div class="no-of-renders">
