        <carousel :per-page="1" :navigationEnabled="true" :paginationEnabled="false">
          <slide v-for="(render,index) in renderData" :key="index" :index="index" @slideclick="swipeEvents">
            <img
              :src="renderData[index].image"
              v-bind:class="{'image-landscape':  screenMode==='landscape'}"
              style="max-width:100vw"
            />
            <div class="carousel-image-container">
              <div class="image-text">
                <p>{{renderData[index].title}}</p>
                <span>{{renderData[index].subtitle}}</span>
              </div>
              <div class="no-of-renders">
