<script>
import { mapState, mapActions } from "vuex";
import { Carousel, Slide } from "vue-carousel";

export default {
  components: { Carousel, Slide },
  middleware: ["initAuth", "authReq"],
  head() {
    return {
      title: "Neo"
    };
  },
  data() {
    return {
      showInvite: false,
      inviteEmail: "",
      currentIndex: 0,
      showLogout: false,
      inviteSend: false,
      codeSend: false,
      getFreeDemoShow: false,
      freeDemoUrl: "https://calendly.com/foyr-neo-product-demo",
      isGalleryShow: false,
      galleryImageIndex: 0,
      screenMode: "potrait"
    };
  },
  mounted() {
    if (this.videosData.length == 0)
      this.fetchVideo().then(res => {
        const video = document.querySelector("video");
        video.addEventListener("play", event => {
          if (window.analytics) {
            window.analytics.track("Neo Video Played", {
              title: "Neo Video played",
              subtitle: "mobile"
            },{'integrations': { "Amplitude": { "session_id": new Date().getTime() } } },{  "timestamp": new Date().getTime() });
          }
        });
        video.addEventListener("pause", event => {
          if (window.analytics) {
            window.analytics.track("Neo Video Pause", {
              title: "Neo Video Pause",
              subtitle: "mobile"
            },{'integrations': { "Amplitude": { "session_id": new Date().getTime() } } },{  "timestamp": new Date().getTime() });
          }
        });
      });
    if (!this.user) this.fetchUser();
    this.fetchRender();
    window.addEventListener("resize", () => {
      this.windowWidth = window.innerWidth;
      console.log(this.landScapeCheck());
    });
  },
  computed: {
    ...mapState({
      videosData: state => state.Dash.video,
      renderData: state => state.Dash.renders,
      user: state => state.User.user
    })
  },
  methods: {
    ...mapActions({
      fetchVideo: "Dash/getVideos",
      logout: "Auth/logout",
      fetchUser: "User/fetch",
      fetchRender: "Dash/getRenders",
      inviteFriend: "Dash/inviteFriend",
      sendOffer: "Dash/sendOffer"
    }),
    landScapeCheck: function() {
      if (window.orientation === 90 || window.orientation === -90) {
        console.log("Landscape");
        this.screenMode = "landscape";
      } else if (window.innerHeight > window.innerWidth) {
        console.log("Potrait");
        this.screenMode = "potrait";
      }
    },
    offerCode() {
      this.sendOffer()
        .then(res => {
          this.codeSend = true;
          this.inviteSend = true;
          this.showInvite = true;
          if (window.analytics) {
            window.analytics.track("Get My Offer Now", {
              title: "Get My Offer Now",
              subtitle: "mobile"
            },{'integrations': { "Amplitude": { "session_id": new Date().getTime() } } },{  "timestamp": new Date().getTime() });
          }
        })
        .catch(err => {
          console.log(err);
        });
    },
    signOut() {
      this.logout().then(res => {
        // amplitude.getInstance().logEvent("logout");
        window.location.href = res.url;
        if (window.analytics) {
          window.analytics.track("Sign Out", {
            title: "Sign Out",
            subtitle: "mobile"
          },{'integrations': { "Amplitude": { "session_id": new Date().getTime() } } },{  "timestamp": new Date().getTime() });
        }
      });
    },
    freeDemo() {
      if (window.chmln) {
        // window.chmln.show(window.location.host == 'neo.foyr.com'?'5df767d051954e0004c16199':'5df093eb6ed37c00040b2875')
      }
      if (window.analytics) {
        window.analytics.track("Get Free Demo Now", {
          title: "Get Free Demo Now",
          subtitle: "mobile"
        },{'integrations': { "Amplitude": { "session_id": new Date().getTime() } } },{  "timestamp": new Date().getTime() });
      }
      // 5df099fe6ed37c00040b3234
    },
    inviteLink() {
      if (this.inviteEmail) {
        this.inviteFriend({ email: this.inviteEmail })
          .then(res => {
            this.codeSend = false;
            this.inviteSend = true;
            this.inviteEmail = "";
            if (window.analytics) {
              window.analytics.track("Refer a Friend", {
                title: "Refer a Friend",
                subtitle: "mobile"
              },{'integrations': { "Amplitude": { "session_id": new Date().getTime() } } },{  "timestamp": new Date().getTime() });
            }
          })
          .catch(err => {
            console.log(err);
          });
      } else {
      }
    },
    // swipeHandler(direction) {
    //   if (window.analytics) {
    //     window.analytics.track("Render Swipe", {
    //       title: "Render Swipe",
    //       subtitle: "mobile"
    //     });
    //   }
    //   if (direction == "left") {
    //     if (this.currentIndex < this.renderData.length - 1)
    //       this.currentIndex = this.currentIndex + 1;
    //     this.$refs.slider.style.left =
    //       "-" +
    //       window.document.getElementsByClassName("render-slider")[0]
    //         .clientWidth *
    //         this.currentIndex +
    //       "px";
    //   }
    //   if (direction == "right") {
    //     if (this.currentIndex > 0) {
    //       this.currentIndex = this.currentIndex - 1;
    //       this.$refs.slider.style.left =
    //         "-" +
    //         window.document.getElementsByClassName("render-slider")[0]
    //           .clientWidth *
    //           this.currentIndex +
    //         "px";
    //     }
    //   }
    // },
    swipeEvents(pageNumber) {
      if (window.analytics) {
        window.analytics.track("Render Swipe", {
          title: "Render Swipe",
          subtitle: "mobile"
        },{'integrations': { "Amplitude": { "session_id": new Date().getTime() } } },{  "timestamp": new Date().getTime() });
      }
    },
    // pointerClick(direction) {
    //   if (direction) this.swipeHandler(direction);
    // },
    onClickVideo() {},
    outsideClick() {
      if (this.getFreeDemoShow) this.getFreeDemoShow = false;
      if (this.showInvite) {
        this.codeSend = false;
        this.inviteSend = false;
        this.showInvite = false;
      }
      if (this.isGalleryShow) {
        this.isGalleryShow = false;
        this.currentIndex = 0;
        this.galleryImageIndex = 0;
        document.querySelector("body").style.overflow = "scroll";
      }
    },
    slider_thum(direction) {
      let totalIndex = Math.floor(this.renderData.length / 3);
      let remainingIndex = this.renderData.length % 3;
      if (direction == "left") {
        // console.log("Leffff Thum", this.currentIndex);
        if (this.currentIndex < (remainingIndex == 0 ? 0 : 1 + totalIndex)) {
          if (this.currentIndex < totalIndex) {
            this.$refs.slider.style.left =
              "-" +
              window.document.getElementsByClassName("thum-container")[0]
                .clientWidth *
                this.currentIndex +
              "px";
            this.currentIndex = this.currentIndex + 1;
          } else if (this.currentIndex === totalIndex) {
            this.$refs.slider.style.left =
              this.$refs.slider.offsetLeft -
              remainingIndex *
                window.document.getElementsByClassName("thum-images")[0]
                  .clientWidth +
              "px";
            // this.currentIndex = this.currentIndex + 1;
          }
        }
      }
      if (direction == "right") {
        if (this.currentIndex < (remainingIndex == 0 ? 0 : 1 + totalIndex)) {
          this.currentIndex = this.currentIndex - 1;

          if (this.currentIndex < totalIndex) {
            this.$refs.slider.style.left =
              "-" +
              window.document.getElementsByClassName("thum-container")[0]
                .clientWidth *
                this.currentIndex +
              "px";
          } else {
            this.$refs.slider.style.left =
              this.$refs.slider.offsetLeft +
              remainingIndex *
                window.document.getElementsByClassName("thum-images")[0]
                  .clientWidth +
              "px";
          }
        }
      }
    },
    thumSelected(index) {
      this.galleryImageIndex = index;
    },
    stopBgScroll() {
      document.querySelector("body").style.overflow = "hidden";
    },
    closeClicked() {
      this.isGalleryShow = false;
      this.currentIndex = 0;
      this.galleryImageIndex = 0;
      window.document.querySelector("body").style.overflow = "scroll";
    }
  }
};
</script>
